window.products.push({"id":704428,"name":"Bioworld Sanrio X Naruto 16Oz Ceramic Mug","category":"homeandappliances","retail price":9.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/71xqhLG+OwL._AC_SL1500_.jpg","description":"With this collectible ceramic mug, you can enjoy your morning coffee with all your favorite SANRIO & NARUTO friends. The limited-edition artwork makes this mug a timeless collectible. Use this mug to heat your favorite warm beverage in the microwave. Load it up on the top shelf of the dishwasher for easy cleaning. This mug's high-quality stoneware insulates beverages and keeps them warm. If you're looking for collectible merchandise from Hello Kitty AND Naruto, nothing compares to this ceramic coffee mug!","images":["https://m.media-amazon.com/images/I/71xqhLG+OwL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Bioworld","source_asin":"B08WJKJYS5","category_path":"Home & Kitchen"},"sku":"BM-704428","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B08WJKJYS5","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B08WJKJYS5","price_pending":true,"merchant_ready":false});
