window.products.push({"id":704902,"name":"Craft E Vinyl - Glossy Dark Green 12\" x 20 ft Roll of Permanent Adhesive-Backed Vinyl for Cricut Cutters, CraftROBO Cutters, Pazzles Cutters, QuicKutz","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/21LpJbooeUL._AC_.jpg","description":"\" 1 Roll of Glossy Dark Green 12 inch x 20 feet Permanent Adhesive Vinyl . Vinyl easily sticks to just about any smooth surface including: cars, computers, glass, mirrors, plastic and walls.  Vinyl can be used for almost anything including: Banners, Bumper Stickers, Decals, Glass, Mirrors, Scrapbooking, Signs, Stickers, Windows, Wraps. Guaranteed to be compatible with craft cutters, die cutters, punches and vinyl sign cutters. Made in USA  NOTE: Actual colors may vary slightly due to differences in computer display capabilities. This is NOT heat press vinyl.  Not for use on interior walls. Vinyl is non-printable-vinyl and it will not work with inkjet or laser printing. \"","images":["https://m.media-amazon.com/images/I/21LpJbooeUL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Craft E Vinyl","source_asin":"B00LU0ASYW","category_path":"Home & Kitchen"},"sku":"BM-704902","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00LU0ASYW","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00LU0ASYW","price_pending":true,"merchant_ready":false});
